import logging
import re
import telnetlib
import time
from ta_messaging.message_sources.message_source_base import MessageSource
from ta_messaging.py3_string import py3_string
from ute_common_abstract_core.network_elem_identification import MmeIdentification, EnbIdentification, UeIdentification
from ta_messaging import message_parser
from ta_messaging.unparsed_message import UnparsedMessage


class EgateMessageSource(MessageSource):
    '''
    Specific message source that implements extracting unparsed messages from EGATE data stream over telnet connection
    '''

    _prompt = 'EGATE>'
    _messages_pattern = re.compile('((?:UE|MME-|ENB-)\d+).*?(?:(value [UD][L]-.*?message c1 \: (\S+) \:.*?)|'
                                   '(value (UE-EUTRA-Capability).*?)|'
                                   '(value S1AP-PDU.*?value (\S+) \:.*?)|'
                                   '(value X2AP-PDU.*?value (\S+) \:.*?))\s(?:(?:\d{2}\:\d{2}\:\d{2}|%s))' % _prompt,
                                   re.DOTALL | re.MULTILINE)

    def __init__(self, queue):
        self._host = 'localhost'
        self._port = 20000
        super(EgateMessageSource, self).__init__(queue)
        self.source_specific_parser = message_parser.EgateMessageParser()
        self._connection = None
        self._connection_timeout = 10
        self.LOG = False
        self._connection = self._get_opened_connection()
        self._start_in_separate_thread()

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        return 'egate-%s_%s' % (self._host, self._port)

    def _get_opened_connection(self):
        t1 = time.time()
        connection = telnetlib.Telnet()
        try:
            connection.open(host=self._host, port=self._port, timeout=self._connection_timeout)
            self.logger.debug('%s Waiting for connection PROMPT' % self)
            connection.read_until(EgateMessageSource._prompt, self._connection_timeout)
            self.logger.debug('%s Login finished' % self)
        except Exception:
            raise
        self.logger.debug('%s Successfully connected after %s' % (self, str(time.time() - t1)))
        return connection

    def _get_protocol_data(self):
        chunk = ""
        while self.is_running.is_set():
            chunk += self._read()
            if self._is_chunk_complete(chunk):
                return chunk
            time.sleep(0.01)
        return None

    def _get_unparsed_messages(self, protocol_data):
        msgs = self._preparse(protocol_data)
        return [self._create_unparsed_message(msg) for msg in msgs]

    def _is_connection(self):
        return True if self._connection else False

    def _close_connection(self):
        self._is_connection()
        self._connection.close()

    def _is_chunk_complete(self, chunk):
        return True if (chunk[-7:] == self._prompt + " ") else False

    def _is_not_empty(self, string):
        return True if string else False

    def _read(self):
        return py3_string(self._connection.read_very_eager())

    def _preparse(self, protocol_data):
        messages = []
        if 'value' in protocol_data:
            messages = EgateMessageSource._messages_pattern.findall(protocol_data)
            self.logger.trace('%s After preparsing: %s' % (self, messages))
        return [list(filter(self._is_not_empty, msg)) for msg in messages]

    def _create_message_owner(self, data):
        match = re.match('(\w+).*?(\d+)', data)
        device_type = match.group(1)
        device_id = match.group(2)
        create_owner_fun = getattr(self, '_create_%s_owner' % device_type.lower())
        owner = create_owner_fun(str(device_id))
        return owner

    def _create_mme_owner(self, device_id):
        device_id = int(device_id)  # wts uses id which is integer
        return MmeIdentification.from_type_id_pairs(identifiers=[('wts', device_id)], specific_for_tool='wts')

    def _create_enb_owner(self, device_id):
        device_id = int(device_id)  # wts uses id which is integer
        return EnbIdentification.from_type_id_pairs(identifiers=[('wts', device_id)], specific_for_tool='wts')

    def _create_ue_owner(self, device_id):
        device_id = int(device_id)  # wts uses id which is integer
        return UeIdentification.from_type_id_pairs(identifiers=[('wts', device_id)], specific_for_tool='wts')

    def _create_unparsed_message(self, msg_tuple):
        msg_tuple = list(msg_tuple)
        owner = self._create_message_owner(msg_tuple[0])
        msg_payload = msg_tuple[1]
        message_type = msg_tuple[2]
        (msg, err, debug) = UnparsedMessage.from_asn1value_msg_type(owner=owner,
                                                                    msg_payload=msg_payload,
                                                                    message_type_value_str=message_type,
                                                                    parser=self.source_specific_parser,
                                                                    meta_data_dict={'occurrence_time': time.time()})
        if debug:
            self.logger.debug(debug)
        if err:
            self.logger.error(err)
            messaging_logger = logging.getLogger('messaging')
            messaging_logger.error(err)
        return msg
